const rules = new Map(
	Object.entries(declarations).map(([id, rule]) => [
		id,
		Object.freeze({
			offSide: rule.offSide,
			...(rule.markers
				? { markers: Object.freeze({ start: new RegExp(rule.markers.start.source, rule.markers.start.flags), end: new RegExp(rule.markers.end.source, rule.markers.end.flags) }) }
				: {}),
		}),
	]),
);

/** Immutable package configuration; caller-owned overrides stay with the Editor. */
export function getLanguageFoldingRules(languageId: string) {
	return rules.get(languageId);
}
